Perhaps we could signal this issue to the user with something like:

```
renv_download_auth_github_pat <- function() {
  
  pat <- Sys.getenv("GITHUB_PAT", unset = NA)
  if (!is.na(pat))
    return(pat)
  
  token <- tryCatch(gitcreds::gitcreds_get(),
                    error = function(e) {
                      if (!requireNamespace("gitcreds", quietly = TRUE)) {
                        warning("GitHub credentials stored using a credential helper require installation of the gitcreds package.", call. = FALSE)
                        }
                      return(NULL)
                      )
  
  if (!is.null(token))
    return(token$password)
  
}
```

