Hi Kevin, I was drafting something related to issue [208](https://github.com/rstudio/renv/issues/208):

```r
renv_dependencies_discover_r_apply_pkgload <- function(node, envir) {

  node <- renv_call_expect(node = node,
    package = "base", methods = c("lapply", "vapply", "sapply"))
  if (is.null(node))
    return(FALSE)

  prototype <- function(..., character.only) {}
  matched <- catch(match.call(prototype, node, expand.dots = FALSE))

  args_dots <- matched[["..."]]

  loads_package <-
    map_lgl(
      args_dots,
      function(x) any(as.character(x) %in% c("library", "require"))
  )
  valid_package_load <- any(loads_package)
  if (!valid_package_load)
    return(FALSE)

  # TRUE when `character.only` is exactly matched
  chonly_exact <- node[["character.only"]] %||% FALSE

  # these arguments might be forwarded from dots in apply functionals as well:
  # `lib.loc`, `mask.ok`, `exclude`, `include.only`
  is_package_arg_candidate <-
    map_lgl(
      args_dots[!loads_package],
      function(x) is.symbol(x) || (is.character(x) && length(x) >= 1L)
    )

  # symbol that contains character vector of package names is probably at
  # first position of apply type functional, but only for positional matching
  package_candidates <-
    args_dots[!loads_package][is_package_arg_candidate]

  is_package_arg <-
    is.na(
      map_int(
        names(package_candidates),
        function (x) {
          pmatch(x, c("lib.loc", "mask.ok", "exclude", "include.only"))
        }
      )
    )

  # there could be other arguments passed along to `library()` or `require()`
  package_arg <-
    package_candidates[is_package_arg][[1L]]

  if (is.symbol(package_arg))
    args <-
      catch(eval(expr = package_arg, envir = envir))
    if (inherits(args, "error"))
      return(FALSE)

  if (is.character(package_arg))
    args <- package_arg

  for (arg in args) {

    ok <-
      is.character(arg) &&
      !is.null(arg)

    if (!ok)
      next

    # add it
    envir[[arg]] <- TRUE
  }

  TRUE

  # if (chonly_exact)
  # {
  #
  # }
}
```

Would be great if you can give some feedback how I can improve that. Thanks! 
Cheers,
Philipp

